custom_css:
/* ============================================================
 * 发送按钮 - 尖头羽毛笔 + 悬停书写动效
 * content: "" 杀掉 FA 图标，background-image 加载笔尖图标
 * :hover 时 ::before transform 模拟书写摆动
 * ============================================================ */
#send_but::before {
  content: "" !important;
  display: inline-block !important;
  width: 1.2em !important;
  height: 1.2em !important;
  background-image: url("https://api.iconify.design/ph/pen-nib-bold.svg?color=%238ec07c") !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-size: contain !important;
  transition: transform 0.3s ease, filter 0.2s ease !important;
  transform-origin: 50% 80% !important;
}

#send_but {
  transition: filter 0.2s ease, opacity 0.2s ease;
  filter: drop-shadow(0 0 2px rgba(142, 192, 124, 0.2));
}

#send_but:hover::before {
  transform: rotate(-8deg) translateX(-2px) !important;
  animation: quill-write 1.5s ease-in-out infinite !important;
}

#send_but:hover {
  filter: drop-shadow(0 0 8px rgba(142, 192, 124, 0.6));
}

#send_but:active {
  filter: drop-shadow(0 0 4px rgba(142, 192, 124, 0.3));
  opacity: 0.8;
}

@keyframes quill-write {
  0%, 100% { transform: rotate(-8deg) translateX(-2px); }
  50% { transform: rotate(5deg) translateX(2px); }
}

/* ============================================================
 * Gruvbox Dark + HarmonyOS Sans SC
 * ============================================================ */

@import url('https://cdn.jsdelivr.net/npm/@lobehub/webfont-harmony-sans-sc/result.css');

:root {
  --font-scale: 0.95;
  --font-mono: 'JetBrains Mono', 'HarmonyOS Sans SC', 'Cascadia Code', 'Consolas', monospace;
}

/* 全局字体（排除图标） */
body, .mes_text, p, div, span:not([class*="hljs"]):not(.fa):not([class*="fa-"]), 
input, textarea, button, select, option, label, h1, h2, h3, h4, h5, h6,
.mes_text, #chat, .mes, .mes_block, .mesText, .mesAliasAndName, .mesIDDisplay,
#send_form, #chat *:not(i):not(.fa):not([class*="fa-"]) {
  font-family: 'HarmonyOS Sans SC', sans-serif !important;
}

/* 代码块字体 */
pre, code, .hljs, .mes_text pre, .mes_text code,
.mes_text .hljs span, .mes_text pre span, .mes_text code span {
  font-family: var(--font-mono) !important;
}

/* 背景 */
body {
  background-color: #1d2021 !important;
}

body::after {
  content: "";
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background-image: 
    repeating-linear-gradient(45deg, transparent, transparent 35px, rgba(142, 192, 124, 0.008) 35px, rgba(142, 192, 124, 0.008) 70px),
    repeating-linear-gradient(-45deg, transparent, transparent 35px, rgba(131, 165, 152, 0.008) 35px, rgba(131, 165, 152, 0.008) 70px);
  pointer-events: none;
  z-index: 0;
}

#chat {
  background-color: transparent !important;
  align-items: stretch;
}

/* 消息气泡 */
.mes {
  background-color: rgba(40, 40, 40, 0) !important;
  backdrop-filter: none !important;
}

.mes_block {
  flex: 1 1 auto !important;
  display: flex !important;
}

.mesAvatarWrapper {
  flex-shrink: 0;
}

/* 楼层号/时间/token 换行不挤占正文 */
.mesIDDisplay, .mes_timer, .tokenCounterDisplay {
  display: block !important;
}

/* 输入栏 */
#send_form {
  background-color: #3c3836 !important;
  border: 1px solid #504945 !important;
  border-radius: 4px;
}

/* 引号 */
.mes_text q {
  font-weight: 500;
  color: #83a598;
  border-left: 3px solid #83a598;
  background-color: rgba(131, 165, 152, 0.1);
  padding-left: 8px;
  padding-right: 4px;
  margin-left: 4px;
  border-radius: 0 4px 4px 0;
  display: inline-block;
}

/* 面板和抽屉边框 */
.drawer, .drawer-content, #left-nav-panel, #right-nav-panel,
#character_popup, #dialogue_popup, .panel {
  border: 1px solid #504945 !important;
  background-color: #282828 !important;
}

/* 分割线 */
hr, .mes hr, .drawer-content hr {
  border-color: #504945 !important;
}

/* 输入框边框 */
textarea, input[type="text"], input[type="password"] {
  border: 1px solid #504945 !important;
  background-color: #1d2021 !important;
  color: #ebdbb2 !important;
}

/* 提示词管理器条目 */
.prompt_manager_template_entry, .prompt_manager_entry {
  border: 1px solid #504945 !important;
}

/* 角色列表分割线 */
#rm_char_list hr {
  border-color: #504945 !important;
}

/* 推理块标题 */
.reasoning_header, .mes_reasoning_header {
  padding-right: 28px;
}

/* 底部三个按钮 */
#send_form .fa-solid, #send_form a {
  transition: filter 0.2s ease;
}

#send_form .fa-solid:hover, #send_form a:hover {
  filter: drop-shadow(0 0 6px rgba(142, 192, 124, 0.5));
}

/* 图标发光（aqua） */
.fa-solid:hover, .interactable:hover {
  filter: drop-shadow(0 0 4px rgba(142, 192, 124, 0.3));
}
